export function landingExample(){
 const plan:TestPlan={version:2,initialPath:'/',steps:[
  {id:'question',action:'fill',locator:{kind:'label',value:'Your question',name:''},value:'Why does this request fail?',note:'Synthetic test value',included:true,sourceAt:2100},
  {id:'submit',action:'click',locator:{kind:'role',value:'button',name:'Submit question'},value:null,note:'',included:true,sourceAt:5200},
 ],assertions:[{id:'success',kind:'text',locator:{kind:'text',value:'Your question was submitted successfully.',name:''},text:'Your question was submitted successfully.'}],expectedBehaviorConfirmed:true};
 return {json:JSON.stringify(plan,null,2),code:exportPlaywright(plan)};
}
export type LandingExample=ReturnType<typeof landingExample>;
